begin;
create table public.expense_book_categories (
 id uuid primary key default gen_random_uuid(), unit text not null check(unit in ('dreamhouse','academy','restaurant88')),
 parent_id uuid references public.expense_book_categories(id), label text not null check(length(trim(label)) between 1 and 100), label_en text not null default '',
 active boolean not null default true,sort_order integer not null default 0,updated_at timestamptz not null default now(),updated_by uuid references public.staff_accounts(id)
);
create unique index expense_book_category_name on public.expense_book_categories(unit,coalesce(parent_id,'00000000-0000-0000-0000-000000000000'::uuid),lower(label));
create table public.expense_book_entries (
 id uuid primary key default gen_random_uuid(),idempotency_key uuid not null,payload_hash text not null,
 unit text not null check(unit in ('dreamhouse','academy','restaurant88')),entry_date date not null,direction text not null check(direction in ('in','out')),
 house_no text not null default '',category_id uuid references public.expense_book_categories(id),group_label text not null default '',category_label text not null default '',
 amount numeric(14,2) not null check(amount>0),memo text not null default '',received_by text not null default '',
 receipts jsonb not null default '[]',receipt_note text not null default '',
 submitted_by uuid not null references public.staff_accounts(id),staff_name text not null,
 status text not null default 'submitted' check(status in ('submitted','approved','rejected')),
 reviewed_by uuid references public.staff_accounts(id),reviewed_at timestamptz,review_note text not null default '',created_at timestamptz not null default now(),
 unique(submitted_by,idempotency_key),check(jsonb_typeof(receipts)='array' and jsonb_array_length(receipts)<=2),
 check(direction='in' or category_id is not null),check(unit<>'dreamhouse' or length(house_no)>0)
);
create index expense_book_entries_unit_date on public.expense_book_entries(unit,entry_date desc,created_at desc);
alter table public.expense_book_categories enable row level security;
alter table public.expense_book_entries enable row level security;
revoke all on public.expense_book_categories,public.expense_book_entries from public,anon,authenticated;
grant select,insert,update on public.expense_book_categories,public.expense_book_entries to service_role;
create function public.expense_book_entry_guard() returns trigger language plpgsql set search_path=pg_catalog,public as $$
begin
 if tg_op='INSERT' then
  if new.status<>'submitted' or new.reviewed_by is not null then raise exception 'INVALID_INITIAL_STATUS';end if;
  if not exists(select 1 from public.staff_accounts where id=new.submitted_by and is_active and (username='admin-abby' or (username='admin-bella' and new.unit='dreamhouse') or id='34ebbb26-9142-4a34-b35f-4fcc4426e27c')) then raise exception 'SUBMITTER_DENIED';end if;
 else
  if old.status<>'submitted' or new.status not in ('approved','rejected') then raise exception 'ALREADY_REVIEWED';end if;
  if (to_jsonb(new)-array['status','reviewed_by','reviewed_at','review_note']) is distinct from (to_jsonb(old)-array['status','reviewed_by','reviewed_at','review_note']) then raise exception 'IMMUTABLE_ENTRY';end if;
  if not exists(select 1 from public.staff_accounts where id=new.reviewed_by and is_active and (username='admin-abby' or id='34ebbb26-9142-4a34-b35f-4fcc4426e27c')) then raise exception 'REVIEWER_DENIED';end if;
 end if;return new;
end $$;
create trigger expense_book_entry_guard before insert or update on public.expense_book_entries for each row execute function public.expense_book_entry_guard();
create function public.expense_book_totals(p_unit text,p_from date,p_to date) returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select jsonb_build_object('forwarded',coalesce(sum(case when direction='in' then amount else -amount end) filter(where status='approved' and entry_date<p_from),0),
 'money_in',coalesce(sum(amount) filter(where status='approved' and direction='in' and entry_date between p_from and p_to),0),
 'money_out',coalesce(sum(amount) filter(where status='approved' and direction='out' and entry_date between p_from and p_to),0),
 'pending',count(*) filter(where status='submitted' and entry_date between p_from and p_to))
 from public.expense_book_entries where unit=p_unit and entry_date<=p_to;
$$;
revoke all on function public.expense_book_totals(text,date,date) from public,anon,authenticated;
grant execute on function public.expense_book_totals(text,date,date) to service_role;


with g as (insert into public.expense_book_categories(unit,label,label_en,sort_order) values ('dreamhouse','급여·수당','Payroll & allowances',0) returning id) insert into public.expense_book_categories(unit,parent_id,label,label_en,sort_order) select 'dreamhouse',g.id,v.ko,v.en,v.n from g cross join (values ('정규 급여','Regular salary',0),('튜터 강사료','Tutor teaching pay',1),('주말·추가근무 보수','Extra work / trip allowance',2)) v(ko,en,n);
